import Root from "./3Escape Hatches/0ReferenceValuewithRef"
import {HandleInput as Fundamental} from "./2Managing State/3PreserrvingandResetting"
import Sub from "./subReLearn"
import Custom from "./customComponent"
import "./ReLearn.css"

import { useRef } from "react"
import { useState } from "react"  

export default function() {
  const [val, setVal] = useState(0)
  const ref = useRef(null)
  function handleClick () {
    if (ref.current===null) {
      ref.current = setInterval(() => {setVal(n => n+1)},1)
    } else {
      clearInterval(ref.current)
      ref.current
    }
  }
  return <>
  <button
  onClick={handleClick}
  >button</button> <br/>
  {val}
  </>
}

